'use strict';

const $=selector=>document.querySelector(selector);
const canvas=$('#work-canvas'),ctx=canvas.getContext('2d'),viewport=$('#canvas-viewport');
const state={channel:1,playing:false,mode:'empty',stage:'calibration',capture:null,image:null,reference:null,solveReferenceId:null,axisMode:'x',axes:{x:null,y:null},axisLengthMm:{x:null,y:null},axisDraft:null,activeMeasurementOrigin:null,activeMeasurementAxis:null,measurementEdit:null,axisEdit:null,gridVisible:false,liveMeasurePoints:[],
  excluded:new Set(),result:null,view:{scale:1,x:0,y:0},space:false,pan:null,hoverMarker:null,
  topCanvas:null,topBounds:null,region:[],measurements:[],measurementDraft:null,dragVertex:-1,dragLine:null,liveRunning:false};

function setStep(step){
  const normalized={capture:'calibration',reference:'calibration',solve:'calibration',live:'validation'}[step]||step;
  const stages=['calibration','region','validation'],currentIndex=stages.indexOf(normalized);
  state.stage=normalized;
  document.querySelectorAll('.steps li').forEach(item=>{const index=stages.indexOf(item.dataset.step);item.classList.toggle('active',item.dataset.step===normalized);item.classList.toggle('completed',index>=0&&index<currentIndex)});
  for(const [name,id] of [['calibration','#calibration-panels'],['region','#region-panels'],['validation','#validation-panels']]){const panel=$(id);if(panel)panel.hidden=name!==normalized}
  const stageInfo={calibration:['1단계','캡처 및 보정','이미지를 캡처하고 X/Y 기준선과 보정 측정선을 설정하세요.'],region:['2단계','탑뷰 영역','전체 탑뷰에서 실제 판별에 사용할 영역을 선택하세요.'],validation:['3단계','결과 검증','실제 검출 마커와 예측 위치를 비교하고 필요하면 보정 화면으로 돌아가세요.']},info=stageInfo[normalized]||stageInfo.calibration,banner=$('#stage-banner');
  if(banner){banner.dataset.stage=normalized;$('#stage-number').textContent=info[0];$('#stage-title').textContent=info[1];$('#stage-description').textContent=info[2]}
  const visual=$('#validation-visual');if(visual)visual.hidden=normalized!=='validation';viewport.hidden=normalized==='validation';
  $('#capture-tools').hidden=normalized!=='calibration';$('#view-tools').hidden=normalized==='validation';
  $('#canvas-edit-tools').hidden=!(normalized==='calibration'&&state.capture&&state.mode==='capture');
  const subtitles={calibration:'1/3 · 캡처하고 실제 좌표 기준을 설정하세요.',region:'2/3 · 원근이 제거된 이미지에서 출력 영역을 정하세요.',validation:'3/3 · 원본 픽셀과 변환된 월드 위치를 나란히 비교하세요.'};if($('#workflow-subtitle'))$('#workflow-subtitle').textContent=subtitles[normalized]||subtitles.calibration
}
function log(value){$('#result-log').textContent=typeof value==='string'?value:JSON.stringify(value,null,2)}
async function post(path,body){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const value=await response.json();if(!response.ok||value.ok===false)throw new Error(value.error||value.stderr||`HTTP ${response.status}`);return value}
function resizeCanvas(){const rect=viewport.getBoundingClientRect(),ratio=devicePixelRatio||1;canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);canvas.style.width=`${rect.width}px`;canvas.style.height=`${rect.height}px`;draw()}
new ResizeObserver(resizeCanvas).observe(viewport);

function selectChannel(channel){state.channel=channel;document.querySelectorAll('#camera-channels button').forEach(button=>button.classList.toggle('active',Number(button.dataset.channel)===channel));if(state.playing)playCamera();else $('#camera-status').textContent=`채널 ${channel} 선택됨`}
document.querySelectorAll('#camera-channels button').forEach(button=>button.onclick=()=>selectChannel(Number(button.dataset.channel)));
function playCamera(){state.playing=true;state.mode='preview';state.capture=null;state.result=null;state.region=[];canvas.hidden=true;$('#camera-frame').hidden=false;$('#camera-frame').src=`/api/camera/video?channel=${state.channel}&t=${Date.now()}`;$('#camera-status').textContent=`채널 ${state.channel} 프리뷰 재생 중`;setStep('capture')}
$('#play-camera').onclick=playCamera;
async function captureCamera(){try{$('#capture-camera').disabled=true;$('#camera-status').textContent='고해상도 캡처와 RTSP 정합용 검출 중…';const payload=await post('/api/camera/detect',{channel:state.channel});state.playing=false;state.capture=payload.result;state.reference=null;state.solveReferenceId=null;state.axisMode='x';state.axes={x:null,y:null};state.axisDraft=null;state.excluded.clear();state.result=null;state.region=[];state.image=await loadImage(state.capture.image_url+`?t=${Date.now()}`);state.mode='capture';$('#camera-frame').src='';$('#camera-frame').hidden=true;canvas.hidden=false;canvas.style.pointerEvents='auto';buildMarkerList();fitView();setStep('reference');$('#camera-status').textContent=`${state.capture.image_size.width}×${state.capture.image_size.height}px 캡처 · X축을 기준 원점에서 드래그하세요.`;log({capture_id:state.capture.capture_id,capture_detection:{ids:state.capture.ids,image_size:state.capture.image_size},rtsp_detection:state.capture.rtsp_detection,alignment:state.capture.rtsp_alignment||state.capture.rtsp_alignment_error})}catch(error){$('#camera-status').textContent=`캡처 실패: ${error.message}`;log(error.message)}finally{$('#capture-camera').disabled=false}}
$('#capture-camera').onclick=()=>{$('#measure-panel').hidden=true;$('#region-panel').hidden=true;$('#result-card').hidden=true;captureCamera()};
function loadImage(src){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error('이미지를 불러오지 못했습니다.'));image.src=src})}

function sourceSize(){if(state.mode==='capture'&&state.image)return{w:state.image.naturalWidth,h:state.image.naturalHeight};if(state.mode==='top'&&state.topCanvas)return{w:state.topCanvas.width,h:state.topCanvas.height};return null}
function fitView(){const size=sourceSize();if(!size)return;const rect=viewport.getBoundingClientRect();state.view.scale=Math.min(rect.width/size.w,rect.height/size.h);state.view.x=(rect.width-size.w*state.view.scale)/2;state.view.y=(rect.height-size.h*state.view.scale)/2;draw()}
function actualView(){const size=sourceSize();if(!size)return;const rect=viewport.getBoundingClientRect();state.view.scale=1;state.view.x=(rect.width-size.w)/2;state.view.y=(rect.height-size.h)/2;draw()}
function zoomAt(factor,x,y){const size=sourceSize();if(!size)return;const old=state.view.scale;const next=Math.max(.03,Math.min(12,old*factor));state.view.x=x-(x-state.view.x)*next/old;state.view.y=y-(y-state.view.y)*next/old;state.view.scale=next;draw()}
$('#fit-view').onclick=fitView;$('#actual-view').onclick=actualView;$('#zoom-in').onclick=()=>zoomAt(1.25,viewport.clientWidth/2,viewport.clientHeight/2);$('#zoom-out').onclick=()=>zoomAt(.8,viewport.clientWidth/2,viewport.clientHeight/2);
$('#grid-toggle').onclick=()=>{state.gridVisible=!state.gridVisible;$('#grid-toggle').textContent=state.gridVisible?'격자 끄기':'격자 켜기';$('#grid-toggle').setAttribute('aria-pressed',String(state.gridVisible));draw()};
canvas.addEventListener('wheel',event=>{event.preventDefault();const p=screenPoint(event);zoomAt(event.deltaY<0?1.12:.89,p.x,p.y)},{passive:false});
function screenPoint(event){const rect=canvas.getBoundingClientRect();return{x:event.clientX-rect.left,y:event.clientY-rect.top}}
function imagePoint(screen){return{x:(screen.x-state.view.x)/state.view.scale,y:(screen.y-state.view.y)/state.view.scale}}
function toScreen(point){return{x:state.view.x+point.x*state.view.scale,y:state.view.y+point.y*state.view.scale}}
function capturePoint(screen){return imagePoint(screen)}
function topPointToWorld(point){const b=state.topBounds;return{x:b.minX+point.x/state.topCanvas.width*(b.maxX-b.minX),y:b.minY+point.y/state.topCanvas.height*(b.maxY-b.minY)}}
function worldToTop(point){const b=state.topBounds;return{x:(point.x-b.minX)/(b.maxX-b.minX)*state.topCanvas.width,y:(point.y-b.minY)/(b.maxY-b.minY)*state.topCanvas.height}}

// 캡처 캔버스 입력은 이 단일 경로가 우선 처리한다. 기존 일반/편집 핸들러와
// 섞이면 pointer capture 순서에 따라 축 드래그가 사라질 수 있다.
canvas.addEventListener('pointerdown',event=>{if(state.mode!=='capture')return;if(event.button===1||state.space){event.preventDefault();event.stopImmediatePropagation();const screen=screenPoint(event);state.pan={screen,x:state.view.x,y:state.view.y};canvas.setPointerCapture(event.pointerId);canvas.style.cursor='grabbing';return}if(event.button!==0)return;event.preventDefault();event.stopImmediatePropagation();const screen=screenPoint(event),point=capturePoint(screen),measurementHandle=nearestMeasurementHandle(screen);if(measurementHandle){state.measurementEdit=measurementHandle;canvas.setPointerCapture(event.pointerId);draw();return}const axisHandles=nearestAxisHandles(screen);if(axisHandles.length&&state.axes.x&&state.axes.y){state.axisEdit=axisHandles;canvas.setPointerCapture(event.pointerId);draw();return}if(!state.axes.x){state.axisMode='x';state.axisDraft={start:point,end:point};$('#camera-status').textContent='X축을 드래그하세요.';canvas.setPointerCapture(event.pointerId);draw();return}if(!state.axes.y){const origin=toScreen(state.axes.x.start);if(Math.hypot(screen.x-origin.x,screen.y-origin.y)>30){$('#camera-status').textContent='Y축은 X축 시작점(공통 원점)에서 시작하세요.';return}state.axisMode='y';state.axisDraft={start:{...state.axes.x.start},end:point};$('#camera-status').textContent='Y축을 드래그하세요.';canvas.setPointerCapture(event.pointerId);draw();return}const snapped=nearestAxisPoint(screen,['x','y'],false);if(!snapped){$('#camera-status').textContent='측정선은 X/Y 기준 선분 위에서 시작하세요.';return}state.activeMeasurementOrigin=snapped.point;state.activeMeasurementAxis=snapped.axis;state.measurementDraft={originPixel:snapped.point,targetPixel:point,axis:snapped.axis};canvas.setPointerCapture(event.pointerId);draw()},{capture:true});
canvas.addEventListener('pointermove',event=>{if(state.mode!=='capture')return;if(state.pan){event.preventDefault();event.stopImmediatePropagation();const screen=screenPoint(event);state.view.x=state.pan.x+screen.x-state.pan.screen.x;state.view.y=state.pan.y+screen.y-state.pan.screen.y;draw();return}if(state.measurementEdit){event.preventDefault();event.stopImmediatePropagation();updateMeasurementHandle(state.measurementEdit,capturePoint(screenPoint(event)));draw();return}if(state.axisEdit){event.preventDefault();event.stopImmediatePropagation();const point=capturePoint(screenPoint(event));state.axisEdit.forEach(handle=>{if(state.axes[handle.axis])state.axes[handle.axis][handle.endpoint]={...point}});draw();return}if(state.axisDraft){event.preventDefault();event.stopImmediatePropagation();state.axisDraft.end=capturePoint(screenPoint(event));draw();return}if(state.measurementDraft){event.preventDefault();event.stopImmediatePropagation();state.measurementDraft.targetPixel=capturePoint(screenPoint(event));draw()}},{capture:true});
canvas.addEventListener('pointerup',event=>{if(state.mode!=='capture')return;event.preventDefault();event.stopImmediatePropagation();if(state.pan){state.pan=null;canvas.style.cursor=state.space?'grab':'crosshair';try{canvas.releasePointerCapture(event.pointerId)}catch(error){}draw();return}if(state.measurementEdit){state.measurementEdit=null;try{canvas.releasePointerCapture(event.pointerId)}catch(error){}draw();return}if(state.axisEdit){state.axisEdit=null;try{canvas.releasePointerCapture(event.pointerId)}catch(error){}draw();return}if(state.axisDraft){const end=capturePoint(screenPoint(event)),start=state.axisDraft.start;state.axisDraft=null;if(Math.hypot(end.x-start.x,end.y-start.y)<12){draw();return}if(state.axisMode==='x'){state.axes.x={start,end};state.axisMode='y';$('#camera-status').textContent='X축 저장됨 · 같은 시작점에서 Y축을 드래그하세요.'}else{state.axes.y={start,end};finishUserAxes()}draw();try{canvas.releasePointerCapture(event.pointerId)}catch(error){}return}if(state.measurementDraft){const start=state.measurementDraft.originPixel,end=capturePoint(screenPoint(event)),axis=state.measurementDraft.axis;state.measurementDraft=null;if(Math.hypot(end.x-start.x,end.y-start.y)>=12){const target=nearestDetectedCorner(screenPoint(event),24);if(target)addMeasurement(target,start,axis);else addFreeMeasurement(end,start,axis)}else $('#camera-status').textContent='짧은 클릭은 무시됩니다. 누른 채 드래그해서 선을 그리세요.';draw();try{canvas.releasePointerCapture(event.pointerId)}catch(error){}}},{capture:true});

canvas.addEventListener('pointerdown',event=>{if(state.mode==='capture')return;const screen=screenPoint(event);if(event.button===1||state.space){event.preventDefault();event.stopPropagation();state.pan={screen,x:state.view.x,y:state.view.y};canvas.setPointerCapture(event.pointerId);return}if(state.mode==='top'){const world=topPointToWorld(imagePoint(screen));const vertex=nearestRegionVertex(screen,13),line=nearestRegionLine(screen,9);if(vertex>=0){state.dragVertex=vertex;canvas.setPointerCapture(event.pointerId)}else if(line>=0){state.dragLine={index:line,start:world,points:state.region.map(p=>({...p}))};canvas.setPointerCapture(event.pointerId)}else if(state.region.length<4){state.region.push(world);if(state.region.length===4){setStep('region');saveRegion()}updateRegionUI();draw()}}});
canvas.addEventListener('pointermove',event=>{if(state.mode==='capture')return;const screen=screenPoint(event);if(state.pan){event.preventDefault();event.stopPropagation();state.view.x=state.pan.x+screen.x-state.pan.screen.x;state.view.y=state.pan.y+screen.y-state.pan.screen.y;draw();return}if(state.dragVertex>=0){state.region[state.dragVertex]=topPointToWorld(imagePoint(screen));updateRegionUI();draw();return}if(state.dragLine){const world=topPointToWorld(imagePoint(screen)),dx=world.x-state.dragLine.start.x,dy=world.y-state.dragLine.start.y,a=state.dragLine.index,b=(a+1)%4;state.region[a]={x:state.dragLine.points[a].x+dx,y:state.dragLine.points[a].y+dy};state.region[b]={x:state.dragLine.points[b].x+dx,y:state.dragLine.points[b].y+dy};updateRegionUI();draw();return}if(state.mode==='top'){const p=topPointToWorld(imagePoint(screen));$('#pointer-status').textContent=`월드 좌표 ${p.x.toFixed(1)}, ${p.y.toFixed(1)} mm`}});
canvas.addEventListener('pointermove',event=>{if(state.mode!=='capture'||state.reference!==null||state.pan)return;const hovered=hitMarker(capturePoint(screenPoint(event)));if(hovered!==state.hoverMarker){state.hoverMarker=hovered;canvas.style.cursor=hovered===null?'crosshair':'pointer';draw()}});
canvas.addEventListener('pointerleave',()=>{if(state.hoverMarker!==null){state.hoverMarker=null;canvas.style.cursor='';draw()}});
canvas.addEventListener('pointerup',event=>{if(state.mode==='capture')return;if(state.pan){event.preventDefault();event.stopPropagation()}if(state.dragVertex>=0||state.dragLine)saveRegion();state.pan=null;state.dragVertex=-1;state.dragLine=null;try{canvas.releasePointerCapture(event.pointerId)}catch(error){}});
// 캡처 화면은 클릭이 아니라 드래그만 처리함. 기존 선택/측정 핸들러보다 먼저 가로채서
// 단순 클릭으로 선이 생기지 않도록 함.
canvas.addEventListener('pointerdown',event=>{if(state.mode!=='capture')return;if(event.button===1||state.space){event.preventDefault();event.stopImmediatePropagation();const screen=screenPoint(event);state.pan={screen,x:state.view.x,y:state.view.y};canvas.setPointerCapture(event.pointerId);canvas.style.cursor='grabbing';return}if(event.button!==0)return;event.preventDefault();event.stopImmediatePropagation();const screen=screenPoint(event),point=capturePoint(screen),handle=nearestMeasurementHandle(screen);if(handle){state.measurementEdit=handle;canvas.setPointerCapture(event.pointerId);draw();return}const axisHandles=nearestAxisHandles(screen);if(axisHandles.length&&state.axes.x&&state.axes.y){state.axisEdit=axisHandles;canvas.setPointerCapture(event.pointerId);draw();return}if(!state.axes.x||!state.axes.y){if(state.axisMode==='y'){const origin=toScreen(state.axes.x.start);if(Math.hypot(screen.x-origin.x,screen.y-origin.y)>24){$('#camera-status').textContent='Y축은 X축 시작점(공통 원점)에서 시작하세요.';return}state.axisDraft={start:{...state.axes.x.start},end:point,snappedAxis:'x'};canvas.setPointerCapture(event.pointerId);draw();return}state.axisDraft={start:point,end:point};canvas.setPointerCapture(event.pointerId);draw();return}const snapped=nearestAxisPoint(screen,['x','y'],false);if(!snapped){$('#camera-status').textContent='측정선은 X/Y 기준 선분 위에서 시작하세요.';return}state.activeMeasurementOrigin=snapped.point;state.activeMeasurementAxis=snapped.axis;state.measurementDraft={originPixel:snapped.point,targetPixel:point,axis:snapped.axis};canvas.setPointerCapture(event.pointerId);draw()},{capture:true});
canvas.addEventListener('pointermove',event=>{if(state.mode!=='capture')return;if(state.pan){event.preventDefault();event.stopImmediatePropagation();const screen=screenPoint(event);state.view.x=state.pan.x+screen.x-state.pan.screen.x;state.view.y=state.pan.y+screen.y-state.pan.screen.y;draw();return}if(state.measurementEdit){event.preventDefault();event.stopImmediatePropagation();updateMeasurementHandle(state.measurementEdit,capturePoint(screenPoint(event)));draw();return}if(state.axisEdit){event.preventDefault();event.stopImmediatePropagation();const point=capturePoint(screenPoint(event));state.axisEdit.forEach(handle=>{if(state.axes[handle.axis])state.axes[handle.axis][handle.endpoint]={...point}});draw();return}if(state.axisDraft){event.preventDefault();event.stopImmediatePropagation();state.axisDraft.end=capturePoint(screenPoint(event));draw();return}if(state.measurementDraft){event.preventDefault();event.stopImmediatePropagation();state.measurementDraft.targetPixel=capturePoint(screenPoint(event));draw()}},{capture:true});
canvas.addEventListener('pointerup',event=>{if(state.mode!=='capture')return;if(state.pan){event.preventDefault();event.stopImmediatePropagation();state.pan=null;canvas.style.cursor=state.space?'grab':'crosshair';try{canvas.releasePointerCapture(event.pointerId)}catch(error){}draw();return}if(state.measurementEdit){event.preventDefault();event.stopImmediatePropagation();state.measurementEdit=null;try{canvas.releasePointerCapture(event.pointerId)}catch(error){}draw();return}if(state.axisEdit){event.preventDefault();event.stopImmediatePropagation();state.axisEdit=null;try{canvas.releasePointerCapture(event.pointerId)}catch(error){}draw();return}if(state.axisDraft){event.preventDefault();event.stopImmediatePropagation();const end=capturePoint(screenPoint(event)),start=state.axisDraft.start;state.axisDraft=null;if(Math.hypot(end.x-start.x,end.y-start.y)<12){draw();return}if(state.axisMode==='x'){state.axes.x={start,end};state.axisMode='y';$('#camera-status').textContent='X축 저장됨 · 같은 시작점에서 Y축을 드래그하세요.'}else{state.axes.y={start,end};finishUserAxes()}draw();try{canvas.releasePointerCapture(event.pointerId)}catch(error){}return}if(state.measurementDraft){event.preventDefault();event.stopImmediatePropagation();const start=state.measurementDraft.originPixel,end=capturePoint(screenPoint(event)),axis=state.measurementDraft.axis;state.measurementDraft=null;if(Math.hypot(end.x-start.x,end.y-start.y)>=12){const target=nearestDetectedCorner(screenPoint(event),24);if(target)addMeasurement(target,start,axis);else addFreeMeasurement(end,start,axis)}else $('#camera-status').textContent='짧은 클릭은 무시됩니다. 누른 채 드래그해서 선을 그리세요.';draw();try{canvas.releasePointerCapture(event.pointerId)}catch(error){}}},{capture:true});
