window.addEventListener('keydown',event=>{if(event.code==='Space'&&!event.repeat){state.space=true;canvas.style.cursor='grab';event.preventDefault()}});window.addEventListener('keyup',event=>{if(event.code==='Space'){state.space=false;canvas.style.cursor=''}});

function finishUserAxes(){const origin=state.axes.x.start;let best=null,distance=Infinity;state.capture.ids.forEach((id,index)=>markerCorners(index).forEach((corner,cornerIndex)=>{const current=Math.hypot(corner.x-origin.x,corner.y-origin.y);if(current<distance){distance=current;best={id,cornerIndex}}}));if(!best){$('#camera-status').textContent='축 시작점에서 검출 코너를 찾지 못했습니다.';return}state.solveReferenceId=best.id;const size=Number($('#marker-size-mm').value);state.previewH=homography4(markerCorners(state.capture.ids.indexOf(best.id)),[{x:0,y:0},{x:size,y:0},{x:size,y:size},{x:0,y:size}]);$('#measure-panel').hidden=false;buildMarkerList();updateSolveButton();setStep('solve');$('#camera-status').textContent='X/Y축 설정 완료 · 다른 점은 누른 채 드래그로 측정하세요.'}

function markerCorners(index){return(state.capture.corners[index]||[]).map(point=>Array.isArray(point)?{x:point[0],y:point[1]}:{x:point.x,y:point.y})}
function nearestMeasurementHandle(screen){let best=null,distance=15;for(let index=state.measurements.length-1;index>=0;index--){const measurement=state.measurements[index];for(const endpoint of ['originPixel','pixel']){const point=toScreen(measurement[endpoint]),current=Math.hypot(point.x-screen.x,point.y-screen.y);if(current<distance){distance=current;best={index,endpoint}}}}return best}
function nearestAxisHandles(screen){const candidates=[];for(const axis of ['x','y']){const line=state.axes[axis];if(!line)continue;for(const endpoint of ['start','end']){const point=toScreen(line[endpoint]),distance=Math.hypot(point.x-screen.x,point.y-screen.y);if(distance<=15)candidates.push({axis,endpoint,point,distance})}}if(!candidates.length)return[];const nearest=candidates.reduce((best,value)=>value.distance<best.distance?value:best);return candidates.filter(value=>Math.hypot(value.point.x-nearest.point.x,value.point.y-nearest.point.y)<=10).map(({axis,endpoint})=>({axis,endpoint}))}
