function drawRegion(){if(!state.region.length)return;const points=state.region.map(worldToTop).map(toScreen);ctx.beginPath();ctx.moveTo(points[0].x,points[0].y);points.slice(1).forEach(p=>ctx.lineTo(p.x,p.y));if(points.length===4)ctx.closePath();ctx.strokeStyle='#26d9ff';ctx.lineWidth=3;ctx.stroke();if(points.length===4){ctx.fillStyle='rgba(38,217,255,.12)';ctx.fill()}points.forEach((p,index)=>{ctx.beginPath();ctx.arc(p.x,p.y,7,0,Math.PI*2);ctx.fillStyle=index===0?'#fff':'#26d9ff';ctx.fill();ctx.strokeStyle='#052b35';ctx.stroke()})}
