function nearestRegionLine(screen,radius){if(state.region.length!==4)return-1;for(let i=0;i<4;i++){const a=toScreen(worldToTop(state.region[i])),b=toScreen(worldToTop(state.region[(i+1)%4])),dx=b.x-a.x,dy=b.y-a.y,length2=dx*dx+dy*dy,t=Math.max(0,Math.min(1,((screen.x-a.x)*dx+(screen.y-a.y)*dy)/(length2||1))),x=a.x+t*dx,y=a.y+t*dy;if(Math.hypot(screen.x-x,screen.y-y)<=radius)return i}return-1}
