function updateRegionUI(){if(state.region.length===4){const width=(distance(state.region[0],state.region[1])+distance(state.region[2],state.region[3]))/2,height=(distance(state.region[1],state.region[2])+distance(state.region[3],state.region[0]))/2;$('#region-size').textContent=`가로 ${width.toFixed(1)} mm · 세로 ${height.toFixed(1)} mm`;$('#start-live').disabled=!state.result?.H_rtsp_pixel_to_world}else{$('#region-size').textContent=`꼭짓점 ${state.region.length}/4`;$('#start-live').disabled=true}}
