function startLive(){if(!state.result.H_rtsp_pixel_to_world){$('#live-status').textContent=state.result.rtsp_alignment_error||'RTSP 정합 행렬이 없습니다.';return}state.liveMeasurePoints=[];$('#live-view').hidden=false;$('#live-original').src=`/api/camera/video?channel=${state.channel}&t=${Date.now()}`;state.liveRunning=true;setStep('live');requestAnimationFrame(renderLive)}
function renderLive(){if(!state.liveRunning)return;const image=$('#live-original'),target=$('#live-top');if(image.naturalWidth){try{const width=(distance(state.region[0],state.region[1])+distance(state.region[2],state.region[3]))/2,height=(distance(state.region[1],state.region[2])+distance(state.region[3],state.region[0]))/2,renderWidth=1200,renderHeight=Math.max(1,Math.round(renderWidth*height/width));if(target.width!==renderWidth||target.height!==renderHeight){target.width=renderWidth;target.height=renderHeight;target.style.aspectRatio=`${renderWidth} / ${renderHeight}`;liveRenderer=createWarpRenderer(target)}const unit=[{x:0,y:0},{x:1,y:0},{x:1,y:1},{x:0,y:1}],worldMap=homography4(unit,state.region);liveRenderer.render(image,invert3(state.result.H_rtsp_pixel_to_world),worldMap);drawLiveMeasurement();$('#live-status').textContent=`RTSP ${image.naturalWidth}×${image.naturalHeight} → 탑뷰에서 두 점을 클릭해 거리 측정`}catch(error){$('#live-status').textContent=error.message}}liveFrame=requestAnimationFrame(renderLive)}
