function drawLiveMeasurement(){const overlay=$('#live-measure-overlay');if(!overlay)return;const overlayRect=overlay.getBoundingClientRect(),content=liveContentRect(),ratio=devicePixelRatio||1;overlay.width=Math.max(1,Math.round(overlayRect.width*ratio));overlay.height=Math.max(1,Math.round(overlayRect.height*ratio));const overlayCtx=overlay.getContext('2d');overlayCtx.setTransform(ratio,0,0,ratio,0,0);overlayCtx.clearRect(0,0,overlayRect.width,overlayRect.height);if(!state.liveMeasurePoints.length)return;const points=state.liveMeasurePoints.map(point=>({x:content.x+point.screenX*content.width,y:content.y+point.screenY*content.height}));overlayCtx.fillStyle='#ffe45c';overlayCtx.strokeStyle='#ffe45c';overlayCtx.lineWidth=3;points.forEach(point=>{overlayCtx.beginPath();overlayCtx.arc(point.x,point.y,7,0,Math.PI*2);overlayCtx.fill()});if(points.length===2){overlayCtx.setLineDash([9,5]);overlayCtx.beginPath();overlayCtx.moveTo(points[0].x,points[0].y);overlayCtx.lineTo(points[1].x,points[1].y);overlayCtx.stroke();overlayCtx.setLineDash([]);const mid={x:(points[0].x+points[1].x)/2,y:(points[0].y+points[1].y)/2},label=`${distance(state.liveMeasurePoints[0].world,state.liveMeasurePoints[1].world).toFixed(1)} mm`;overlayCtx.font='700 15px system-ui';const width=overlayCtx.measureText(label).width;overlayCtx.fillStyle='rgba(5,10,15,.88)';overlayCtx.fillRect(mid.x-width/2-8,mid.y-26,width+16,23);overlayCtx.fillStyle='#ffe45c';overlayCtx.fillText(label,mid.x-width/2,mid.y-9)}}
$('#live-measure-overlay').addEventListener('click',event=>{if(!state.liveRunning)return;const overlayRect=$('#live-measure-overlay').getBoundingClientRect(),content=liveContentRect(),screenX=Math.max(0,Math.min(1,(event.clientX-overlayRect.left-content.x)/content.width)),screenY=Math.max(0,Math.min(1,(event.clientY-overlayRect.top-content.y)/content.height)),world=livePointToWorld(event);if(state.liveMeasurePoints.length===2)state.liveMeasurePoints=[];state.liveMeasurePoints.push({screenX,screenY,world});drawLiveMeasurement()});
