  let best=null,distance=14;
  state.measurements.forEach((measurement,index)=>{const current=pointToSegmentDistance(screen,toScreen(measurement.originPixel),toScreen(measurement.pixel));if(current<distance){distance=current;best={type:'measurement',index,screen}}});
  for(const axis of ['x','y']){const line=state.axes[axis];if(!line)continue;const current=pointToSegmentDistance(screen,toScreen(line.start),toScreen(line.end));if(current<distance){distance=current;best={type:'axis',axis,screen}}}
